 <div className="settings-section control-stack"><div><h3>Glass blur <span>{settings.blur}px</span></h3><input type="range" aria-label="Glass blur" min="0" max="40" value={settings.blur} onChange={e=>setSettings(s=>({...s,blur:Number(e.target.value)}))}/></div></div>
